import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { expect, test } from "@playwright/test";

// Generated by backend/scripts/qa-real-workflow.js against the isolated QA DB.
const seedPath = join(process.env.TEMP || process.env.TMPDIR || tmpdir(), "schoolflow-qa", "playwright-seed.json");
const seed = JSON.parse(readFileSync(seedPath, "utf8"));

const DAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
let uiTimetable = null;

test.describe.configure({ mode: "serial" });

// Capture browser console errors, uncaught page errors, and failing HTTP
// responses. The guest-to-authenticated bootstrap legitimately probes
// /auth/me and /auth/refresh before a session exists, so those two 401s are
// classified as expected; every other error fails the test.
function captureBrowserErrors(page) {
  const captured = { console: [], pageErrors: [], http: [] };
  page.on("console", (message) => {
    if (message.type() !== "error") return;
    const location = message.location()?.url || "";
    if (/favicon/i.test(location)) return;
    captured.console.push({ text: message.text(), url: location });
  });
  page.on("pageerror", (error) => captured.pageErrors.push(error.message));
  page.on("response", (response) => {
    if (response.status() < 400) return;
    captured.http.push({ status: response.status(), url: response.url() });
  });
  return captured;
}

function assertCleanBrowser(captured) {
  const expectedBootstrap401 = (entry) =>
    entry.status === 401 && /\/api\/v1\/auth\/(me|refresh)(\?|$)/.test(entry.url);
  // The academic setup page deliberately attempts the teacher lookup and
  // degrades gracefully when the role lacks users:manage (e.g. principal).
  const expectedTeacherLookupDenial = (entry) =>
    entry.status === 403 && /\/api\/v1\/users\?role=teacher/.test(entry.url);
  const unexpectedHttp = captured.http.filter((entry) => !expectedBootstrap401(entry) && !expectedTeacherLookupDenial(entry));
  const unexpectedConsole = captured.console.filter((entry) => !/401 \(Unauthorized\)|403 \(Forbidden\)/.test(entry.text));

  expect(captured.pageErrors, `uncaught page errors: ${captured.pageErrors.join(" | ")}`).toEqual([]);
  expect(unexpectedHttp, `unexpected HTTP errors: ${JSON.stringify(unexpectedHttp)}`).toEqual([]);
  expect(unexpectedConsole, `unexpected console errors: ${JSON.stringify(unexpectedConsole)}`).toEqual([]);
}

async function login(page, { email, schoolSlug = seed.schoolSlug }) {
  await page.goto("/login");
  await page.locator('input[name="schoolSlug"]').fill(schoolSlug);
  await page.locator('input[name="email"]').fill(email);
  await page.locator('input[name="password"]').fill(seed.password);
  await page.getByRole("button", { name: /^Sign in$/ }).click();
  await page.waitForURL((url) => !url.pathname.startsWith("/login"));
  await expect(page.locator("h1").first()).toBeVisible();
}

async function openAdminTimetable(page) {
  await page.goto("/academics");
  await expect(page.getByRole("heading", { name: "Academic setup" })).toBeVisible();
  await page.locator('[data-academic-tab="timetable"]').click();
  await expect(page.locator("tbody tr").first()).toBeVisible();
}

async function pickFreeSlot(page) {
  const used = new Set(await page.locator("tbody tr").evaluateAll((rows) => rows.map((row) => {
    const day = row.cells?.[0]?.textContent?.trim() || "";
    const period = Number(row.cells?.[1]?.textContent?.trim());
    return `${day}|${period}`;
  })));
  for (let day = 2; day <= 7; day += 1) {
    for (let period = 2; period <= 20; period += 1) {
      if (!used.has(`${DAY_NAMES[day - 1]}|${period}`)) return { day, period };
    }
  }
  throw new Error("No free timetable slot found in the seeded academic session");
}

async function expectNoHorizontalOverflow(page) {
  const layout = await page.evaluate(() => ({
    documentWidth: document.documentElement.scrollWidth,
    viewportWidth: window.innerWidth
  }));
  expect(layout.documentWidth, `horizontal overflow at ${layout.viewportWidth}px`).toBeLessThanOrEqual(layout.viewportWidth + 2);
}

test("admin creates a timetable entry in the real UI and verifies it after reload", async ({ page }) => {
  const captured = captureBrowserErrors(page);
  await login(page, { email: seed.adminEmail });
  await openAdminTimetable(page);

  await expect(page.locator("tbody tr").filter({ hasText: "QA-101" })).toHaveCount(1);
  const slot = await pickFreeSlot(page);
  const room = `QA-UI-${Date.now().toString(36).toUpperCase()}`;
  uiTimetable = { ...slot, room };

  await page.getByRole("button", { name: /Add timetable/i }).click();
  await page.locator('select[name="academicSessionId"]').selectOption(seed.sessionId);
  await page.locator('select[name="sectionId"]').selectOption(seed.sectionId);
  await page.locator('select[name="classSubjectId"]').selectOption(seed.classSubjectId);
  await page.locator('input[name="dayOfWeek"]').fill(String(slot.day));
  await page.locator('input[name="periodNumber"]').fill(String(slot.period));
  await page.locator('input[name="startsAt"]').fill("09:00");
  await page.locator('input[name="endsAt"]').fill("09:45");
  await page.locator('input[name="room"]').fill(room);
  await page.getByRole("button", { name: "Create record" }).click();

  await expect(page.getByText("Timetable record created.")).toBeVisible();
  await expect(page.locator("tbody tr").filter({ hasText: room })).toHaveCount(1);

  await page.reload();
  await openAdminTimetable(page);
  const createdRow = page.locator("tbody tr").filter({ hasText: room });
  await expect(createdRow).toHaveCount(1);
  await expect(createdRow).toContainText(DAY_NAMES[slot.day - 1]);
  await expect(createdRow).toContainText(String(slot.period));
  await expect(page.locator("tbody tr").filter({ hasText: "QA-101" })).toHaveCount(1);
  assertCleanBrowser(captured);
});

test("teacher sees the persisted timetable in the real UI", async ({ page }) => {
  test.skip(!uiTimetable, "admin timetable creation did not complete");
  const captured = captureBrowserErrors(page);
  await login(page, { email: seed.teacherEmail });
  await page.goto("/academics");
  await expect(page.getByRole("heading", { name: "My timetable" })).toBeVisible();
  await expect(page.locator("tbody tr").filter({ hasText: uiTimetable.room })).toHaveCount(1);
  await expect(page.locator("tbody tr").filter({ hasText: "QA-101" })).toHaveCount(1);
  assertCleanBrowser(captured);
});

test("principal sees the persisted timetable in the real UI", async ({ page }) => {
  test.skip(!uiTimetable, "admin timetable creation did not complete");
  const captured = captureBrowserErrors(page);
  await login(page, { email: seed.principalEmail });
  await expect(page.getByRole("heading", { name: /Good .*,/ })).toBeVisible();
  await openAdminTimetable(page);
  await expect(page.locator("tbody tr").filter({ hasText: uiTimetable.room })).toHaveCount(1);
  assertCleanBrowser(captured);
});

test("parent dashboard resolves class and section names in the real UI", async ({ page }) => {
  const captured = captureBrowserErrors(page);
  await login(page, { email: seed.parentEmail });
  await expect(page.getByRole("heading", { name: /^Welcome,/ })).toBeVisible();
  await expect(page.getByText("QaStudent One")).toBeVisible();
  await expect(page.getByText("Grade 1")).toBeVisible();
  await expect(page.getByText(/^enrolled$/i).first()).toBeVisible();
  assertCleanBrowser(captured);
});

test("platform admin dashboard loads in the real UI", async ({ page }) => {
  const captured = captureBrowserErrors(page);
  await login(page, { email: seed.platformEmail, schoolSlug: "" });
  await expect(page.getByRole("heading", { name: "Platform overview" })).toBeVisible();
  await expect(page.getByText("Customer schools").first()).toBeVisible();
  await expect(page.getByText("Active plans").first()).toBeVisible();
  assertCleanBrowser(captured);
});

test("responsive layouts render without console errors or page overflow", async ({ page }) => {
  const captured = captureBrowserErrors(page);
  await login(page, { email: seed.adminEmail });
  const widths = [1440, 1280, 768, 390, 360];

  await page.goto("/");
  for (const width of widths) {
    await page.setViewportSize({ width, height: 900 });
    await expect(page.locator(".page-intro h1"), `dashboard h1 at ${width}px, url=${page.url()}`).toBeVisible();
    await expectNoHorizontalOverflow(page);
  }

  await page.goto("/academics");
  await expect(page.getByRole("heading", { name: "Academic setup" })).toBeVisible();
  for (const width of widths) {
    await page.setViewportSize({ width, height: 900 });
    await expect(page.getByRole("heading", { name: "Academic setup" }), `academics h1 at ${width}px, url=${page.url()}`).toBeVisible();
    await expectNoHorizontalOverflow(page);
  }
  assertCleanBrowser(captured);
});
